        when t.tile -> 'cofre' ? 'legendId'
          then t.tile || jsonb_build_object(
            'cofre', jsonb_build_object(
              'objetoId', (
                select id from public.objetos
                where nombre = case (t.tile -> 'cofre' ->> 'legendId')::int
                  when 1 then 'Banco de trabajo'
                  when 2 then 'Hacha'
                  when 3 then 'Tijeras'
                  when 4 then 'Cuerda'
                  when 5 then 'Poción'
                  when 6 then 'Pico'
                end
                limit 1
              ),
              'cantidad', 1
            )
          )
        else t.tile
      end
      order by t.ordinality
    ) as nuevos_tiles
  from bioma, jsonb_array_elements(bioma.tiles->'tiles') with ordinality as t(tile, ordinality)
  group by bioma.id
)
update public.biomas b
set tiles = jsonb_set(b.tiles, '{tiles}', r.nuevos_tiles)
from resueltos r
where b.id = r.id;

update public.progreso_jugador p
set posicion_q = 29, posicion_r = 29
from public.biomas b
where b.id = p.bioma_actual_id and b.nombre = 'Desierto';

update public.descubrimiento_jugador d
set casillas_descubiertas = '[]'::jsonb,
    cofres_abiertos = '[]'::jsonb,
    recursos_recolectados = '[]'::jsonb,
    puentes_construidos = '[]'::jsonb,
    cuerdas_construidas = '[]'::jsonb
from public.biomas b
where b.id = d.bioma_id and b.nombre = 'Desierto';

-- Verificación 1: no debería quedar ningún cofre con legendId sin resolver.
select tile
from public.biomas, jsonb_array_elements(tiles->'tiles') as tile
where nombre = 'Desierto'
  and tile -> 'cofre' ? 'legendId';

-- Verificación 2: los 6 cofres deberían tener objetoId no nulo.
select tile->>'x' as x, tile->>'y' as y, tile->'cofre' as cofre
from public.biomas, jsonb_array_elements(tiles->'tiles') as tile
where nombre = 'Desierto'
  and tile ? 'cofre';

-- Verificación 3: conteo de elementos.
select
  count(*) filter (where tile->>'tipo' = 'montana') as montana,
  count(*) filter (where tile->>'tipo' = 'rio') as rio,
  count(*) filter (where tile->>'tipo' = 'cactus') as cactus,
  count(*) filter (where tile->>'tipo' = 'roca_clase') as roca_clase,
  count(*) filter (where tile->>'recurso' = 'madera') as madera,
  count(*) filter (where tile->>'recurso' = 'piedra') as piedra,
  count(*) filter (where tile->>'recurso' = 'lana') as lana,
  count(*) filter (where tile ? 'cofre') as cofres
from public.biomas, jsonb_array_elements(tiles->'tiles') as tile
where nombre = 'Desierto';

-- Verificación 4: enemigos/jefe_final guardados a nivel raíz del JSONB.
select
  jsonb_array_length(tiles->'enemigos') as cantidad_enemigos,
  tiles->'jefe_final' as jefe_final
from public.biomas
where nombre = 'Desierto';
